import os
import sys


_initializer = None
_decoder = None


class Initializer(object):

    def __init__(self, multi_base_folder, **kwargs):
        super(Initializer, self).__init__(**kwargs)
        self._multi_base_folder = multi_base_folder
        self.decoder_class = None
        self._set_decoder_class()
        self._set_exception_handling_configuration()

    def _set_decoder_class(self):
        try:
            from multidynamic.itf.L2Log.Du.Ps.Messages.StreamComponentInd_t import StreamComponentInd_t
        except ImportError:
            sys_path = sys.path[:]
            try:
                self._set_multi_classes_path()
                from L2Log.Du.Ps.Messages.StreamComponentInd_t import StreamComponentInd_t
            finally:
                sys.path = sys_path[:]
        self.decoder_class = StreamComponentInd_t

    def _set_multi_classes_path(self):
        """
        Set the system path needed to access the MuLTI-generated python decoder classes.
        """
        path_list = [self._multi_base_folder,
                     self._multi_base_folder + '/5G_L2-DU-PS_TCG/itf',
                     self._multi_base_folder + '/TtiTracesEvents']
        for path in path_list:
            assert os.path.exists(path), "Path {0} not found!".format(path)
        for path in path_list:
            if path not in sys.path:
                sys.path.append(path)

    @staticmethod
    def _set_exception_handling_configuration():
        """
        Set the needed configuration for the exception handling during message decoding by MuLTI-generated decoders.
        """
        from multi.error.terminator import terminator

        class CustomizedReporter(terminator.Reporter):
            def report(self, *args):
                pass

        class CustomizedDefenceAction(terminator.DefenceAction):
            def execute(self, *args):
                return AssertionError(*args)

        terminator.attach_reporter(CustomizedReporter())
        terminator.attach_defence_action(CustomizedDefenceAction())


def initialize(multi_base_folder):
    global _decoder, _initializer

    _initializer = Initializer(
        multi_base_folder=multi_base_folder)
    _decoder = create_decoder()


def create_decoder():
    return _initializer.decoder_class()


def get_decoder_size():
    return _decoder.size
